components.css:
.ds-badge { font-family: var(--mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap; background: none; border: 0; border-radius: 0; padding: 0; }
.ds-badge::before { content: "["; }
.ds-badge::after { content: "]"; }
.ds-badge-pending { color: var(--pending, #C39BE8); }

.ds-metric { background: none; border: 0; border-bottom: 1px solid var(--rule, #262B32); border-radius: 0; padding: 12px 20px 16px 0; }
.ds-metric-label { font-family: var(--mono, ui-monospace, monospace); font-size: 0.6875rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-2, #98A0AC); margin-bottom: 8px; }
.ds-metric-value { font-family: var(--mono, ui-monospace, monospace); font-size: 1rem; font-weight: 500; color: var(--text, #E4E7EC); line-height: 1.2; }
.ds-metric-rel { margin-top: 8px; padding-left: 12px; font-family: var(--mono, ui-monospace, monospace); font-size: 0.6875rem; line-height: 1.45; color: var(--text-3, #8E96A2); }

.ds-table-scroll { overflow-x: auto; overscroll-behavior-x: contain; }
.ds-table { width: 100%; border-collapse: collapse; font-family: var(--mono, ui-monospace, monospace); font-size: 0.8125rem; font-variant-numeric: tabular-nums; }
.ds-table thead th { font-size: 0.6875rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-2, #98A0AC); text-align: left; padding: 8px 16px 8px 0; border-bottom: 1px solid var(--rule-strong, #39404A); white-space: nowrap; }
.ds-table tbody td { padding: 8px 16px 8px 0; border-bottom: 1px solid var(--rule, #262B32); vertical-align: baseline; }
.ds-table td.num, .ds-table th.num { text-align: right; }
.ds-table tbody tr.best td { font-weight: 700; color: var(--text, #E4E7EC); }
.ds-table-footer { margin: 0 0 20px; padding-top: 8px; border-top: 1px solid var(--rule, #262B32); font-family: var(--mono, ui-monospace, monospace); font-size: 0.6875rem; line-height: 1.5; color: var(--text-3, #8E96A2); max-width: 120ch; }

.ds-session { position: sticky; top: 0; z-index: 10; display: flex; align-items: center; gap: 20px; padding: 8px 20px; background: var(--surface, #14171B); border-bottom: 1px solid var(--rule-strong, #39404A); font-family: var(--mono, ui-monospace, monospace); font-size: 0.75rem; }
.ds-session-id { color: var(--text, #E4E7EC); font-weight: 700; letter-spacing: 0.14em; text-decoration: none; }
.ds-session-nav a::before { content: "/"; color: var(--text-3, #8E96A2); margin-right: 2px; }
.ds-session-context { display: flex; flex-wrap: wrap; gap: 4px 20px; padding: 8px 20px; background: var(--ground, #0D0F12); border-bottom: 1px solid var(--rule, #262B32); font-family: var(--mono, ui-monospace, monospace); font-size: 0.6875rem; color: var(--text-2, #98A0AC); overflow-wrap: anywhere; }
.ds-session-context b { font-weight: 500; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-3, #8E96A2); margin-right: 4px; }

.ds-progress { height: 3px; background: var(--rule, #262B32); overflow: hidden; border-radius: 0; }
.ds-progress-fill { height: 100%; width: 100%; transform: scaleX(0); transform-origin: left; background: var(--accent, #5B9DFF); transition: transform 0.55s cubic-bezier(0.16, 1, 0.3, 1); }
.ds-progress[data-progress-mode="measuring"] .ds-progress-fill { transform: none; transition: none; mask-image: linear-gradient(90deg, transparent 0%, #000 38%, #000 62%, transparent 100%); mask-size: 46% 100%; mask-repeat: no-repeat; animation: ds-measuring 1900ms cubic-bezier(0.45, 0, 0.55, 1) infinite; }
@keyframes ds-measuring { from { mask-position: -50% 0; } to { mask-position: 110% 0; } }
@media (prefers-reduced-motion: reduce) { .ds-progress-fill { transition: none; } .ds-progress[data-progress-mode="measuring"] .ds-progress-fill { animation: none; } }

.ds-empty { padding: 20px 0; border: 0; border-top: 1px solid var(--rule, #262B32); border-radius: 0; background: none; text-align: left; margin: 0; }
.ds-empty-msg { font-family: var(--mono, ui-monospace, monospace); font-size: 0.8125rem; color: var(--text-2, #98A0AC); margin: 0 0 8px; }
.ds-hint { color: var(--text-3, #8E96A2); font-size: 0.75rem; margin: 0; }
